/** Verify actual published/staged ranking presentation, without route or time mocks. */
import {chromium} from 'playwright';import {mkdir,writeFile} from 'node:fs/promises';import assert from 'node:assert/strict';
const base=process.env.BASE_URL||'https://courtside-tennis.pages.dev/',dir=process.env.REPORT_DIR||'phase2/ranking-evidence-live';await mkdir(dir,{recursive:true});
const report={url:base,startedAt:new Date().toISOString(),checks:[],errors:[],networkMocks:false,fakeClock:false},ok=name=>report.checks.push({name,passed:true});
const browser=await chromium.launch();const page=await browser.newPage({viewport:{width:1440,height:1000}});page.on('pageerror',e=>report.errors.push(e.message));
try{
 await page.goto(base+'?ranking-review='+Date.now(),{waitUntil:'networkidle',timeout:40000});await page.locator('#nav a[href="#players"]').click();await page.locator('#rank-body tr').first().waitFor();
 const data=await page.evaluate(async()=>{const url=window.CourtRuntime.publishedDataURL('data/content.json',document.baseURI,window.COURTSIDE_CONFIG);const r=await fetch(url+'?review='+Date.now());if(!r.ok)throw Error('Data HTTP '+r.status);return r.json();});
 report.revision=data.meta.revision;assert.ok(data.meta.appliedReviews.includes('2026-10-11-official-ranking-review'));assert.equal(await page.locator('#rank-body tr').count(),100);assert.equal(await page.locator('#rank-body .player-age').count(),100);assert.equal(await page.locator('#rank-body .rank-review-dot').count(),11);assert.match(await page.locator('[data-rank-review="ATP"]').innerText(),/11 人待复核/);ok('ATP remains a full 100-player table with only the 11 unresolved entries marked');
 await page.locator('[data-rank-review="ATP"]').click();const pending=page.locator('.ranking-evidence').filter({hasText:'11 人待复核'});await pending.locator('summary').click();assert.equal(await pending.locator('.ranking-discrepancies>div').count(),11);assert.match(await pending.innerText(),/5,260/);assert.match(await pending.innerText(),/5,560/);assert.match(await pending.innerText(),/不代表原数值已确认无误/);ok('two conflicting source values remain visible as alternatives, not a fabricated combined ranking');await page.locator('.close-dialog').click();
 await page.locator('[data-action="rankTour"][data-value="WTA"]').click();assert.equal(await page.locator('#rank-body tr').count(),100);assert.equal(await page.locator('#rank-body .player-age').count(),100);assert.equal(await page.locator('#rank-body .rank-review-dot').count(),0);assert.match(await page.locator('.ranking-period').innerText(),/2026-10-05/);assert.match(await page.locator('[data-rank-review="WTA"]').innerText(),/本期官方核对/);ok('WTA retains its verified October 5 table and 100 visible age labels');await page.screenshot({path:dir+'/wta-ranking.png'});
 const blinkova=page.locator('#rank-body tr[data-rank="89"]');assert.match(await blinkova.innerText(),/法国/);await blinkova.locator('[data-action="player"]').click();await page.locator('#dialog-body details.provenance summary').click();assert.equal(await page.locator('#dialog-body a[href="https://www.wtatennis.com/players/324267/anna-blinkova"]').count(),1);assert.match(await page.locator('#dialog-body details.provenance').innerText(),/代表国家／地区：法国/);ok('Blinkova retains official France representation with a direct primary-source link');await page.locator('.close-dialog').click();
 await page.locator('[data-rank-review="WTA"]').click();const official=page.locator('.ranking-evidence').filter({hasText:'本期官方核对'});await official.locator('summary').click();assert.match(await official.innerText(),/完整前100/);assert.match(await official.innerText(),/9月28日/);assert.match(await official.innerText(),/不代表实时或自动更新/);await page.screenshot({path:dir+'/wta-evidence.png'});ok('WTA official evidence explains the rejected older API issue without claiming automatic collection');await page.locator('.close-dialog').click();
 const views=await page.evaluate(d=>d.rankings.map(t=>window.CourtCore.rankingReview(t)),data);assert.equal(views[0].state,'conflict');assert.equal(views[1].state,'official-reviewed');assert.equal(data.players.find(p=>p.id==='carlos-alcaraz').points,5260);ok('the browser uses the exact bound review while preserving sporting values');
 const mobile=await browser.newPage({viewport:{width:390,height:844},hasTouch:true,isMobile:true,timezoneId:'America/Los_Angeles'});mobile.on('pageerror',e=>report.errors.push(e.message));await mobile.goto(base+'?review-mobile='+Date.now(),{waitUntil:'networkidle'});await mobile.locator('#nav a[href="#players"]').tap();await mobile.locator('#rank-body tr').first().waitFor();assert.ok(await mobile.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));await mobile.screenshot({path:dir+'/mobile-atp-review.png'});await mobile.locator('[data-action="rankTour"][data-value="WTA"]').tap();assert.match(await mobile.locator('[data-rank-review="WTA"]').innerText(),/本期官方核对/);assert.ok(await mobile.evaluate(()=>document.documentElement.scrollWidth<=innerWidth));ok('390px touch layout preserves both tour switches and readable secondary review labels');
 assert.deepEqual(report.errors,[]);ok('no browser JavaScript exceptions');report.passed=true;
}catch(e){report.passed=false;report.failure=e.stack;process.exitCode=1;await page.screenshot({path:dir+'/failure.png'}).catch(()=>{});}finally{report.finishedAt=new Date().toISOString();await writeFile(dir+'/ranking-browser.json',JSON.stringify(report,null,2));console.log(JSON.stringify(report,null,2));await browser.close();}
